class TFMListBase
{
    Name name;
    Map	baseChildren;

}

Method.Source:
public void new()
{
    baseChildren = new Map(Types::Integer,Types::Class);
}

	public str ParmName(str _name = name)
    {
        SysDictClass			sdc;
        TFMListELementAttribute	attr;
		if (!name && !_name)
        {
            sdc = new SysDictClass(classIdGet(this));
            attr = sdc.getAttribute(classStr(TFMListELementAttribute));
            name = attr ? attr.parmName() : subStr(classId2Name(classIdGet(this)),8,1000);
		}
		else
        {
            name = _name;
        }

        return name;
    }

/// <summary>
/// Output for XML
/// </summary>
/// <param name = "_parent"></param>
public void appendToXML(XmlElement _parent, boolean _expandCustomComponents)

{
    TFMListBase elem;
    MapEnumerator mEnum = baseChildren.getEnumerator();
    XmlElement currentElement;

    str currentName = this.ParmName();
    if(currentName)
    {
        currentElement = _parent.ownerDocument().createElement(currentName);
        _parent.appendChild(currentElement);
    } 
    else
    {
        currentElement = _parent;
    }

    while(mEnum.moveNext())
    {
        elem = mEnum.currentValue();
        elem.appendToXML(currentElement, _expandCustomComponents);
    }
}

/// <summary>
/// Output for render format
/// </summary>
/// <param name = "_parent"></param>
public void render(TFMListVisualizationInterface _visualizer)
{
    _visualizer.render(this);
}

public str replaceTextWithValue(str _text, Map _valuesMap)
{
    int posStart=1, posEnd;
    str textBetweenBrackets;
    str text = _text;
    str textToPutInstead;
    while (posStart)
    {
        posStart = strScan(text,'{',posEnd,1000);
        if (!posStart)
        {
            break;
        }
        posEnd = strScan(text,'}',posStart,1000);
        textBetweenBrackets = subStr(text,posStart+1,posEnd-posStart-1);
        if (_valuesMap != null)
        {
            textToPutInstead = _valuesMap.exists(textBetweenBrackets) ? _valuesMap.lookup(textBetweenBrackets) : '';
            /*if (!textToPutInstead && dataBindingView)
            {
                textToPutInstead = '{'+textBetweenBrackets+'}';
            }*/
            text = strReplace(text, '{'+textBetweenBrackets+'}', textToPutInstead);
            posEnd -= (strLen(textBetweenBrackets) + 2);
            posEnd += strLen(textToPutInstead);
        }
    }
    return text;
}
